// src/pages/Dashboard.jsx
import React, { useEffect, useState } from "react";
import { useTheme } from "../context/ThemeContext";
import { getMyReports } from "../api/thesis";
import { useNavigate } from "react-router-dom";

const Dashboard = () => {
  const { colors } = useTheme();
  const navigate = useNavigate();

  const [reports, setReports] = useState([]);

  useEffect(() => {
    getMyReports().then(setReports);
  }, []);

  return (
    <div style={{ background: colors.pageBg, minHeight: "100vh", padding: 40 }}>
      <h1 style={{ color: colors.text }}>My Thesis Checks</h1>

      <div style={{ marginTop: 30, display: "grid", gap: 16 }}>
        {reports.map((r) => (
          <div
            key={r.id}
            onClick={() => navigate(`/report?id=${r.id}`)}
            style={{
              background: colors.cardBg,
              padding: 20,
              borderRadius: 14,
              cursor: "pointer",
            }}
          >
            <h3>Thesis #{r.id}</h3>
            <p>Status: <b>{r.status}</b></p>
            <p>Plagiarism: {r.plagiarism_score ?? "—"}%</p>
            <p>AI Score: {r.ai_score ?? "—"}%</p>
            <p>Grammar issues: {r.grammar_issues ?? "—"}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Dashboard;
